import { spawn } from 'node:child_process';

const bin = '/harness-state/.bun/bin/gbrain';
const child = spawn(bin, ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, PATH: `/harness-state/.bun/bin:${process.env.PATH}`, GBRAIN_HOME: '/harness-state' },
  stdio: ['pipe', 'pipe', 'pipe'],
});

let buf = '';
const pending = new Map();
let nextId = 1;

child.stderr.on('data', (d) => process.stderr.write('[srv] ' + d.toString()));

child.stdout.on('data', (d) => {
  buf += d.toString();
  let idx;
  while ((idx = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, idx).trim();
    buf = buf.slice(idx + 1);
    if (!line) continue;
    let msg;
    try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
    }
  }
});

function send(method, params) {
  const id = nextId++;
  const payload = { jsonrpc: '2.0', id, method, params };
  child.stdin.write(JSON.stringify(payload) + '\n');
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    setTimeout(() => { if (pending.has(id)) { pending.delete(id); reject(new Error('timeout ' + method)); } }, 60000);
  });
}

function notify(method, params) {
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method, params }) + '\n');
}

const out = {};
try {
  out.initialize = await send('initialize', {
    protocolVersion: '2025-06-18',
    capabilities: {},
    clientInfo: { name: 'openclaw-probe', version: '1.0.0' },
  });
  notify('notifications/initialized', {});
  const tools = await send('tools/list', {});
  out.toolNames = (tools.tools || []).map((t) => t.name);

  out.remember = await send('tools/call', {
    name: 'remember',
    arguments: {
      fact: 'MCP round-trip marker GBX-MCP-2026-11-18: gbrain MCP server answered remember/recall over stdio from OpenClaw host f61609ca62ca.',
      entity: 'gbrain-install-check',
      content_origin: 'user_said',
      provenance: 'install-check: OpenClaw MCP stdio round trip, 2026-11-18',
    },
    _meta: { hot_memory: 'off' },
  });
  out.recall = await send('tools/call', {
    name: 'recall',
    arguments: { query: 'GBX-MCP-2026-11-18' },
    _meta: { hot_memory: 'off' },
  });
} catch (e) {
  out.error = String(e.message);
}
console.log(JSON.stringify(out, null, 2).slice(0, 4000));
child.stdin.end();
child.kill();
process.exit(0);

