import { spawn } from 'node:child_process';
const child = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'], {
  env: { ...process.env, PATH: `/harness-state/.bun/bin:${process.env.PATH}`, GBRAIN_HOME: '/harness-state' },
  stdio: ['pipe','pipe','pipe'] });
let buf=''; const pending=new Map(); let id=1;
child.stdout.on('data', d => { buf+=d.toString(); let i; while((i=buf.indexOf('\n'))>=0){ const l=buf.slice(0,i).trim(); buf=buf.slice(i+1); if(!l) continue; let m; try{m=JSON.parse(l)}catch{continue} if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(new Error(JSON.stringify(m.error))):p.resolve(m.result);} } });
const send=(method,params)=>{const n=id++;child.stdin.write(JSON.stringify({jsonrpc:'2.0',id:n,method,params})+'\n');return new Promise((res,rej)=>{pending.set(n,{resolve:res,reject:rej});setTimeout(()=>{if(pending.has(n)){pending.delete(n);rej(new Error('timeout'))}},60000)})};
await send('initialize',{protocolVersion:'2025-06-18',capabilities:{},clientInfo:{name:'openclaw-probe',version:'1.0.0'}});
child.stdin.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized',params:{}})+'\n');
for (const q of ['GBX-MCP-2026-11-18','GBX-2026-11-18']) {
  const r = await send('tools/call',{name:'recall',arguments:{query:q},_meta:{hot_memory:'off'}});
  const texts = (r.content||[]).map(c=>c.text).join('\n');
  console.log('QUERY', q, '=>', texts.slice(0,900));
  console.log('---');
}
child.kill(); process.exit(0);
EOF
